      SUBROUTINE DBEND2CC     CALCULATES PARTIAL DERIVATIVES OF THE SECOND-ORDERC     TRANSFER MATRIX OF A BENDING MAGNETC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'HSINT.CIN'      INCLUDE 'HSINTA.CIN'      INCLUDE 'HPINT.CIN'      INCLUDE 'HPINTA.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TERMS.CIN'      INCLUDE 'VSINT.CIN'      INCLUDE 'VSINTA.CIN'      INCLUDE 'VPINT.CIN'      INCLUDE 'VPINTA.CIN'      INCLUDE 'WMN.CIN'CC     LOCAL VARIABLESC      REAL             DBEB, DBEP, GLOP, H, HEX, RH, WM5N C-------------------------------------------------------------------------------C      IF (JV .EQ. NBDB .OR. JV .EQ. NK2) GO TO 10      IF (JV .EQ. NBDBP .OR. JV .EQ. NK2P) GO TO 50      GO TO 100CC     VARIATION OF SEXTUPOLE COMPONENTC   10 IF (SOFA) LINEAR = .FALSE.      DBEB = DPARM/(H0*UNITI(1))**2      IF (JV .EQ. NK2) DBEB = DBEB/(H0*UNITI(8))**3      WM5N = 1.0 - 5.0*NB + RMPS*(2.0 - 5.0*NB)      HEX = RMPS*H0      H = H0 + HEX      RH = 1.0 + RMPSC      RV(1,1) = RV(1,1) + 2.0*HEX*H0*DBEB*HSCDX      RV(1,2) = RV(1,2) + 2.0*RMPS*DBEB*HSSDX      RV(1,6) = RV(1,6) + 2.0*HEX*DBEB*HSDX2      RV(2,1) = RV(2,1) + 2.0*HEX*H0*DBEB*HPCDX      RV(2,2) = RV(2,2) + 2.0*HEX*DBEB*H0*HPSDX      RV(2,6) = RV(2,6) + 2.0*HEX*DBEB*HPDX2      RV(3,3) = RV(3,3) - 2.0*HEX*DBEB*H0*VSDCM      RV(3,4) = RV(3,4) - 2.0*RMPS*DBEB*VSDSM      RV(4,3) = RV(4,3) - 2.0*HEX*DBEB*H0*VPDCM      RV(4,4) = RV(4,4) - 2.0*HEX*DBEB*H0*VPDSMC      TV(1,1) = - H0**2*H*DBEB*HSCX2      TV(1,2) = - 2.0*H0**2*H*DBEB*HSCSX      TV(1,3) = - DBEB*H*HSSX2      TV(1,6) = H0**2*H*DBEB*HSCY2      TV(1,9) = 2.0*H*DBEB*HSCSY      TV(1,10) = H*DBEB*HSSY2      TV(1,16) = - 2.0*H0*H*DBEB*HSCDX      TV(1,17) = - 2.0*RH*DBEB*HSSDX      TV(1,21) = - H*DBEB*HSDX2      TV(2,1) = - H0**2*H*DBEB*HPCX2      TV(2,2) = - 2.0*H0**2*H*DBEB*HPCSX      TV(2,3) = - H0**2*H*DBEB*HPSX2      TV(2,6) = H0**2*H*DBEB*HPCY2      TV(2,9) = 2.0*H0**2*H*DBEB*HPCSY      TV(2,10) = H*DBEB*HPSY2      TV(2,16) = - 2.0*DBEB*H0*H*HPCDX      TV(2,17) = - 2.0*H0*H*DBEB*HPSDX      TV(2,21) = - H*DBEB*HPDX2      TV(3,4) = 2.0*H0**2*H*DBEB*VSCCM      TV(3,5) = 2.0*H*DBEB*VSSCM      TV(3,5) = 2.0*H*DBEB*VSCSM      TV(3,8) = 2.0*H*DBEB*VSSSM      TV(3,18) = 2.0*H0*H*DBEB*VSDCM      TV(3,19) = 2.0*RH*DBEB*VSDSM      TV(4,4) = 2.0*H0**2*H*DBEB*VPCCM      TV(4,5) = 2.0*H0**2*H*DBEB*VPSCM      TV(3,5) = 2.0*H0**2*H*DBEB*VPCSM      TV(4,8) = 2.0*H*DBEB*VPSSM      TV(4,18) = 2.0*H0*H*DBEB*VPDCM      TV(4,19) = 2.0*H0*H*DBEB*VPDSM      TV(5,1) = H0**2*DBEB*(3.0*L - SX*CX - 2.0*SX)/(6.0*WMN)      TV(5,2) = 2.0*DBEB*(1.0 - CX)/(3.0*WMN**2)     1        - 2.0*H0**2*DBEB*SX**2/(6.0*WMN)      TV(5,3) = DBEB*(3.0*L - 4.0*SX + SX*CX)/(6.0*WMN**2)      TV(5,6) = - DBEB*(2.0*H0**2*(1.0 - 3.0*NB)*(L - SX)/WMN     1        - H0**2*(L - SY*CY))/(2.0*WM5N)      TV(5,9) = - DBEB*(H0**2*SY**2/WM5N     1        - 2.0*(1.0 - CX)/(WM5N*WMN))      IF (NB .NE. 0.0) GLOP = (L - SY*CY)/(2.0*NB)      IF (NB .EQ. 0.0) GLOP = H0**2*L**3/3.0      TV(5,10) = - DBEB*(GLOP - 2.0*(L - SX)/WMN)/WM5N      TV(5,16) = DBEB*(H0*SMLCX/WMN**2     1         - 2.0*H0*(L - SX)/(3.0*WMN**2)     2         - H0*(L - SX*CX)/(3.0*WMN**2))      TV(5,17) = DBEB*(4.0*H0*DISN/(3.0*WMN**2)     1         + (H0*L*SX - H0*SX**2/3.0)/WMN**2)      TV(5,21) = DBEB*(4.0*(L - SX)/3.0 - SX + L*CX     1         + (L - CX*SX)/6.0)/WMN**3      GO TO 100CC     VARIATION OF SKEW SEXTUPOLE COMPONENTC   50 IF (SOFA) LINEAR = .FALSE.      DBEP = DPARM*RNMS/(H0*UNITI(1))**2      IF (JV .EQ. NK2P) DBEP = DBEP/(H0*UNITI(8))**3C      TV(1,4) = 2.0*DBEP*H0**3*HSCCM      TV(1,7) = 2.0*DBEP*H0*HSCSM      TV(1,5) = 2.0*DBEP*H0*HSSCM      TV(1,8) = 2.0*DBEP*H0*HSSSM      TV(1,18) = 2.0*DBEP*HSDCM      TV(1,19) = 2.0*DBEP*HSDSM      TV(2,4) = 2.0*DBEP*H0**3*HPCCM      TV(2,7) = 2.0*DBEP*H0**3*HPCSM      TV(2,5) = 2.0*DBEP*H0**3*HPSCM      TV(2,8) = 2.0*DBEP*H0*HPSSM      TV(2,18) = 2.0*DBEP*H0**2*HPDCM      TV(2,19) = 2.0*DBEP*H0**2*HPDSM      TV(3,1) = DBEP*H0**3*VSCX2      TV(3,2) = 2.0*DBEP*H0*VSCSX      TV(3,3) = DBEP*H0*VSSX2      TV(3,16) = 2.0*DBEP*VSCDX      TV(3,17) = 2.0*DBEP*VSSDX      TV(3,21) = DBEP*H0*VSDX2      TV(3,6) = - DBEP*H0**3*VSCY2      TV(3,9) = - 2.0*DBEP*H0**3*VSCSY      TV(3,10) = - DBEP*H0*VSSY2      TV(4,1) = DBEP*H0**3*VPCX2      TV(4,2) = 2.0*DBEP*H0**3*VPCSX      TV(4,3) = DBEP*H0*VPSX2      TV(4,16) = 2.0*DBEP*H0**2*VPCDX      TV(4,17) = 2.0*DBEP*VPSDX      TV(4,21) = DBEP*H0*VPDX2      TV(4,6) = - DBEP*H0**3*VPCY2      TV(4,9) = - 2.0*DBEP*H0**3*VPCSY      TV(4,10) = - DBEP*H0**3*VPSY2C  100 RETURN      END